contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 kink, uint256 slope0, uint256 slope1, address asset) public payable {
        bool invalidKink = (kink >= 1e27 || kink == 0);
        bool reverted;

        try c.setSlopes(asset, IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == invalidKink);
    }

    receive() external payable {}
}

